"""CM operations"""
import os
from taf.ul.trs_e2e_fw.lib.ems.nom.nom_base import NomBase


class CMOperations(NomBase):

    def __init__(self):
        super(CMOperations, self).__init__()

    def export(self, **kwargs):
        file_name = kwargs.pop('file_name', 'exported_actual_config.xml')
        dist_names = kwargs.pop('dist_names', self.bts_moc_id)
        dest_path = 'execution_logs'
        exported_file_path = '{}/{}'.format(dest_path, file_name)
        if not os.path.exists(dest_path):
            os.makedirs(dest_path)
        self.nom_factory.nom.export_plan(path=exported_file_path, scope=dist_names)
        return exported_file_path
